46:     fn export<W: Write>(&self, dataset: &FlightDataset, writer: &mut W) -> Result<(), ExportError> {
47:         if dataset.points.is_empty() {
48:             let empty_fc = json!({
49:                 "type": "FeatureCollection",
50:                 "features": []
51:             });
52:             if self.options.pretty {
53:                 serde_json::to_writer_pretty(writer, &empty_fc)?;
54:             } else {
55:                 serde_json::to_writer(writer, &empty_fc)?;
56:             }
57:             return Ok(());
58:         }
59: 
60:         let mut min_lon = f64::INFINITY;
61:         let mut min_lat = f64::INFINITY;
62:         let mut min_alt = f64::INFINITY;
63:         let mut max_lon = f64::NEG_INFINITY;
64:         let mut max_lat = f64::NEG_INFINITY;
65:         let mut max_alt = f64::NEG_INFINITY;
66: 
67:         let mut coordinates = Vec::with_capacity(dataset.points.len());
68:         let mut times = Vec::new();
69:         let mut speeds = Vec::new();
70:         let mut altitudes_agl = Vec::new();
71:         let mut battery_pcts = Vec::new();
72:         let mut pitches = Vec::new();
73:         let mut rolls = Vec::new();
74:         let mut yaws = Vec::new();
75: 
76:         for pt in &dataset.points {
77:             let lon = Self::sanitize_float(pt.longitude);
78:             let lat = Self::sanitize_float(pt.latitude);
79:             let alt = Self::sanitize_float(pt.altitude_msl);
80: 
81:             if lon < min_lon { min_lon = lon; }
82:             if lon > max_lon { max_lon = lon; }
83:             if lat < min_lat { min_lat = lat; }
84:             if lat > max_lat { max_lat = lat; }
85:             if alt < min_alt { min_alt = alt; }
86:             if alt > max_alt { max_alt = alt; }
87: 
88:             // RFC 7946 § 3.1.1 strictly mandates [lon, lat, alt]
89:             coordinates.push(vec![lon, lat, alt]);
90: 
91:             if self.options.include_coordinate_properties {
92:                 times.push(Self::sanitize_float(pt.elapsed_s));
93:                 speeds.push(Self::sanitize_float(pt.ground_speed_mps));
94:                 altitudes_agl.push(Self::sanitize_float(pt.altitude_agl));
95:                 battery_pcts.push(pt.battery_pct);
96:                 pitches.push(Self::sanitize_float(pt.pitch_deg));
97:                 rolls.push(Self::sanitize_float(pt.roll_deg));
98:                 yaws.push(Self::sanitize_float(pt.yaw_deg));
99:             }
100:         }
101: 
102:         let first_pt = dataset.points.first().unwrap();
103:         let last_pt = dataset.points.last().unwrap();
104: 
105:         let mut trajectory_props = json!({
106:             "name": "Flight Trajectory",
107:             "altitudeMode": "absolute",
108:             "startTime": first_pt.timestamp_iso8601,
109:             "endTime": last_pt.timestamp_iso8601,
110:             "durationSeconds": Self::sanitize_float(dataset.metadata.duration_seconds),
111:             "totalDistanceMeters": Self::sanitize_float(dataset.metadata.total_distance_meters),
112:             "maxAltitudeAglMeters": Self::sanitize_float(dataset.metadata.max_altitude_agl_m),
113:             "maxAltitudeMslMeters": Self::sanitize_float(dataset.metadata.max_altitude_msl_m),
114:             "maxSpeedMps": Self::sanitize_float(dataset.metadata.max_horizontal_speed_mps),
115:             "pointCount": dataset.points.len(),
116:             "aircraftModel": dataset.metadata.aircraft_model.as_deref().unwrap_or("Unknown"),
117:         });
118: 
119:         if self.options.include_coordinate_properties {
120:             trajectory_props["coordinateProperties"] = json!({
121:                 "times": times,
122:                 "speeds": speeds,
123:                 "altitudesAgl": altitudes_agl,
124:                 "batteryPercents": battery_pcts,
125:                 "pitches": pitches,
126:                 "rolls": rolls,
127:                 "yaws": yaws,
128:             });
129:         }
130: 
131:         // Feature 1: 3D Trajectory LineString
132:         let trajectory_feature = json!({
133:             "type": "Feature",
134:             "id": "flight-trajectory",
135:             "geometry": {
136:                 "type": "LineString",
137:                 "coordinates": coordinates
138:             },
139:             "properties": trajectory_props
140:         });
141: 
142:         let mut features = vec![trajectory_feature];
143: 
144:         // Feature 2: Takeoff Point
145:         let takeoff_pt = dataset
146:             .points
147:             .iter()
148:             .find(|p| p.is_motor_on)
149:             .unwrap_or(first_pt);
150: 
151:         features.push(json!({
152:             "type": "Feature",
153:             "id": "takeoff-point",
154:             "geometry": {
155:                 "type": "Point",
156:                 "coordinates": [takeoff_pt.longitude, takeoff_pt.latitude, takeoff_pt.altitude_msl]
157:             },
158:             "properties": {
159:                 "name": "Takeoff Point",
160:                 "timestamp": takeoff_pt.timestamp_iso8601,
161:                 "elevationMsl": takeoff_pt.altitude_msl,
162:                 "elevationMslMeters": takeoff_pt.altitude_msl
163:             }
164:         }));
165: 
166:         // Feature 3: Home Point
167:         if let (Some(h_lat), Some(h_lon), Some(h_alt)) = (
168:             dataset.metadata.home_latitude,
169:             dataset.metadata.home_longitude,
170:             dataset.metadata.home_altitude_msl,
171:         ) {
172:             features.push(json!({
173:                 "type": "Feature",
174:                 "id": "home-point",
175:                 "geometry": {
176:                     "type": "Point",
177:                     "coordinates": [h_lon, h_lat, h_alt]
178:                 },
179:                 "properties": {
180:                     "name": "Home Point",
181:                     "rthAltitude": dataset.metadata.rth_altitude_m.unwrap_or(30.0),
182:                     "elevationMslMeters": h_alt
183:                 }
184:             }));
185:         }
186: 
187:         // Feature 4: RTH Event
188:         for ev in &dataset.events {
189:             if ev.event_type == FlightEventType::RthTriggered {
190:                 if let (Some(lat), Some(lon)) = (ev.latitude, ev.longitude) {
191:                     features.push(json!({
192:                         "type": "Feature",
193:                         "id": "rth-event",
194:                         "geometry": {
195:                             "type": "Point",
196:                             "coordinates": [lon, lat, ev.altitude_msl.unwrap_or(first_pt.altitude_msl)]
197:                         },
198:                         "properties": {
199:                             "name": "RTH Triggered",
200:                             "description": ev.description,
201:                             "timestamp": DateTime::from_timestamp_millis(ev.timestamp_utc_ms)
202:                                 .map(|dt| dt.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
203:                                 .unwrap_or_else(|| "1970-01-01T00:00:00.000Z".to_string())
204:                         }
205:                     }));
206:                 }
207:             }
208:         }
209: 
210:         // Feature 5: Landing Point
211:         features.push(json!({
212:             "type": "Feature",
213:             "id": "landing-point",
214:             "geometry": {
215:                 "type": "Point",
216:                 "coordinates": [last_pt.longitude, last_pt.latitude, last_pt.altitude_msl]
217:             },
218:             "properties": {
219:                 "name": "Landing Point",
220:                 "timestamp": last_pt.timestamp_iso8601,
221:                 "elevationMslMeters": last_pt.altitude_msl
222:             }
223:         }));
224: 
225:         let fc = json!({
226:             "type": "FeatureCollection",
227:             "bbox": [min_lon, min_lat, min_alt, max_lon, max_lat, max_alt],
228:             "features": features
229:         });
