+#[test]
+fn test_geojson_single_point_trajectory_rfc7946_linestring_min_positions() {
+    let mut ds = FlightDataset::default();
+    ds.metadata.aircraft_model = Some("DJI Mini 4 Pro".to_string());
+    ds.metadata.home_latitude = Some(36.2415);
+    ds.metadata.home_longitude = Some(-116.8258);
+    ds.metadata.home_altitude_msl = Some(-86.0);
+
+    let mut pt = canonical_cruise_dataset().points.remove(0);
+    pt.latitude = 36.2415;
+    pt.longitude = -116.8258;
+    pt.altitude_msl = -86.0;
+    pt.altitude_agl = 5.0;
+    pt.ground_speed_mps = 0.0;
+    ds.points.push(pt);
+
+    let exporter = GeoJsonExporter::default();
+    let json_str = exporter.export_to_string(&ds).expect("GeoJSON export failed for single point");
+
+    let root: Value = serde_json::from_str(&json_str).expect("Must be valid JSON");
+    assert_eq!(root["type"], "FeatureCollection");
+
+    // 1. Verify 3D bbox enclosure for single point: [minX, minY, minZ, maxX, maxY, maxZ]
+    let bbox = root["bbox"].as_array().expect("Must have bbox array");
+    assert_eq!(bbox.len(), 6, "3D bbox must have 6 elements");
+    assert_eq!(bbox[0].as_f64().unwrap(), -116.8258);
+    assert_eq!(bbox[1].as_f64().unwrap(), 36.2415);
+    assert_eq!(bbox[2].as_f64().unwrap(), -86.0);
+    assert_eq!(bbox[3].as_f64().unwrap(), -116.8258);
+    assert_eq!(bbox[4].as_f64().unwrap(), 36.2415);
+    assert_eq!(bbox[5].as_f64().unwrap(), -86.0);
+
+    // 2. Verify LineString coordinates count satisfies RFC 7946 §3.1.4 (>= 2 positions)
+    let features = root["features"].as_array().unwrap();
+    let traj = features.iter().find(|f| f["id"] == "flight-trajectory").expect("flight-trajectory feature must exist");
+    assert_eq!(traj["geometry"]["type"], "LineString");
+
+    let coords = traj["geometry"]["coordinates"].as_array().expect("coordinates must be an array");
+    assert_eq!(
+        coords.len(),
+        2,
+        "LineString MUST have at least 2 positions per RFC 7946 §3.1.4 even for single-point datasets"
+    );
+    assert_eq!(coords[0], coords[1], "Single-point trajectory coordinates must be duplicated");
+    assert_eq!(coords[0][0].as_f64().unwrap(), -116.8258);
+    assert_eq!(coords[0][1].as_f64().unwrap(), 36.2415);
+    assert_eq!(coords[0][2].as_f64().unwrap(), -86.0);
+
+    // 3. Properties check
+    let props = &traj["properties"];
+    assert_eq!(props["pointCount"], 1, "pointCount reflects true telemetry records count");
+
+    // 4. Verify landmark points exist and are valid Point geometries
+    assert!(features.iter().any(|f| f["id"] == "takeoff-point" && f["geometry"]["type"] == "Point"));
+    assert!(features.iter().any(|f| f["id"] == "home-point" && f["geometry"]["type"] == "Point"));
+    assert!(features.iter().any(|f| f["id"] == "landing-point" && f["geometry"]["type"] == "Point"));
+}
