+fn test_geojson_single_point_coordinate_properties_duplication() {
+    let mut ds = FlightDataset::default();
+    let pt = canonical_cruise_dataset().points.remove(0);
+    ds.points.push(pt);
+
+    let exporter = GeoJsonExporter::new(GeoJsonOptions {
+        include_coordinate_properties: true,
+        ..Default::default()
+    });
+    let json_str = exporter.export_to_string(&ds).expect("GeoJSON export failed");
+
+    let root: Value = serde_json::from_str(&json_str).unwrap();
+    let traj = root["features"].as_array().unwrap().iter().find(|f| f["id"] == "flight-trajectory").unwrap();
+    let coord_props = &traj["properties"]["coordinateProperties"];
+
+    let times = coord_props["times"].as_array().unwrap();
+    let speeds = coord_props["speeds"].as_array().unwrap();
+    let altitudes_agl = coord_props["altitudesAgl"].as_array().unwrap();
+    let battery_pcts = coord_props["batteryPercents"].as_array().unwrap();
+    let pitches = coord_props["pitches"].as_array().unwrap();
+    let rolls = coord_props["rolls"].as_array().unwrap();
+    let yaws = coord_props["yaws"].as_array().unwrap();
+
+    // Verify all property arrays match coordinates length of 2
+    assert_eq!(times.len(), 2, "coordinateProperties times array must match coordinates length (2)");
+    assert_eq!(speeds.len(), 2);
+    assert_eq!(altitudes_agl.len(), 2);
+    assert_eq!(battery_pcts.len(), 2);
+    assert_eq!(pitches.len(), 2);
+    assert_eq!(rolls.len(), 2);
+    assert_eq!(yaws.len(), 2);
+
+    assert_eq!(times[0], times[1]);
+    assert_eq!(speeds[0], speeds[1]);
