+    let mut ds = canonical_cruise_dataset();
+    ds.points.truncate(2);
+    ds.metadata.total_records = 2;
+
+    let exporter = GeoJsonExporter::new(GeoJsonOptions {
+        include_coordinate_properties: true,
+        ..Default::default()
+    });
+    let json_str = exporter.export_to_string(&ds).expect("GeoJSON export failed");
+
+    let root: Value = serde_json::from_str(&json_str).unwrap();
+    let traj = root["features"].as_array().unwrap().iter().find(|f| f["id"] == "flight-trajectory").unwrap();
+    let coords = traj["geometry"]["coordinates"].as_array().unwrap();
+
+    assert_eq!(coords.len(), 2, "Two-point trajectory must have exactly 2 positions without duplication");
+    assert_ne!(coords[0], coords[1], "Two distinct positions must not be identical");
+
